<form method="POST" action="{{ $incident ? route('saas-ops.incident-reports.update',$incident) : route('saas-ops.incident-reports.store') }}" class="rounded-xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900">@csrf @if($incident) @method('PUT') @endif<div class="grid gap-4 md:grid-cols-2"><select name="school_id" class="rounded-lg dark:bg-slate-950"><option value="">Platform-wide</option>@foreach($schools as $school)<option value="{{ $school->id }}" @selected(old('school_id',$incident?->school_id)==$school->id)>{{ $school->name }}</option>@endforeach</select><input name="title" value="{{ old('title',$incident?->title) }}" placeholder="title" class="rounded-lg dark:bg-slate-950"><select name="severity" class="rounded-lg dark:bg-slate-950">@foreach(['sev1','sev2','sev3','sev4'] as $severity)<option value="{{ $severity }}" @selected(old('severity',$incident?->severity)===$severity)>{{ $severity }}</option>@endforeach</select><select name="status" class="rounded-lg dark:bg-slate-950">@foreach(['open','investigating','mitigated','resolved','closed'] as $status)<option value="{{ $status }}" @selected(old('status',$incident?->status ?? 'open')===$status)>{{ $status }}</option>@endforeach</select><select name="owner_id" class="rounded-lg dark:bg-slate-950"><option value="">No owner</option>@foreach($users as $user)<option value="{{ $user->id }}" @selected(old('owner_id',$incident?->owner_id)==$user->id)>{{ $user->name }}</option>@endforeach</select></div>@foreach(['impact','root_cause','mitigation','corrective_action'] as $field)<textarea name="{{ $field }}" class="mt-3 w-full rounded-lg dark:bg-slate-950" placeholder="{{ $field }}">{{ old($field,$incident?->{$field}) }}</textarea>@endforeach<button class="mt-3 rounded-lg bg-lime-500 px-4 py-2 text-sm font-black text-white">Simpan</button></form>
